/** Supported support-ticket lifecycle states. */
export type TicketStatus = "open" | "pending" | "resolved" | "closed";
/** Ticket urgency determines the first-response SLA target. */
export type TicketPriority = "low" | "medium" | "high" | "urgent";
/** Agent ticket projection; timestamps are UTC ISO strings. */
export type HelpdeskTicket = {
	id: string;
	subject: string;
	status: TicketStatus;
	priority: TicketPriority;
	customerId: string;
	requesterEmail: string | null;
	assigneeId: string | null;
	slaDueAt: string;
	firstRespondedAt: string | null;
	resolvedAt: string | null;
	createdAt: string;
	updatedAt: string;
};
/** Customer projection excludes assignment, ownership and SLA internals. */
export type CustomerTicket = Pick<
	HelpdeskTicket,
	| "id"
	| "subject"
	| "status"
	| "priority"
	| "resolvedAt"
	| "createdAt"
	| "updatedAt"
>;
/** Agent conversation entry, including internal notes. */
export type HelpdeskMessage = {
	id: string;
	ticketId: string;
	body: string;
	authorId: string;
	authorType: "customer" | "agent";
	isInternalNote: boolean;
	createdAt: string;
};
/** Public conversation entry, without private actor identifiers or note flags. */
export type CustomerMessage = Pick<
	HelpdeskMessage,
	"id" | "ticketId" | "body" | "authorType" | "createdAt"
>;
/** Customer detail contains only public messages. */
export type CustomerTicketDetail = CustomerTicket & {
	messages: CustomerMessage[];
};
/** Agent detail contains public replies and internal notes. */
export type HelpdeskTicketDetail = HelpdeskTicket & {
	messages: HelpdeskMessage[];
};
/** Reusable agent reply text. */
export type HelpdeskCannedReply = {
	id: string;
	title: string;
	body: string;
	createdAt: string;
	updatedAt: string;
};
/** Server-side list filters and pagination. */
export type HelpdeskListParams = {
	/** Literal case-insensitive subject/conversation search; trimmed NFC text, at most 200 UTF-16 code units. */
	search?: string;
	status?: TicketStatus;
	priority?: TicketPriority;
	assigneeId?: string;
	limit?: number;
	offset?: number;
};
/** Per-priority first-response targets in elapsed minutes. */
export type HelpdeskSlaTargets = Record<TicketPriority, number>;
/** Database ticket row; lockVersion is never exposed to clients. */
export type TicketRecord = Omit<
	HelpdeskTicket,
	"slaDueAt" | "firstRespondedAt" | "resolvedAt" | "createdAt" | "updatedAt"
> & {
	lockVersion: string;
	slaDueAt: Date;
	firstRespondedAt: Date | null;
	resolvedAt: Date | null;
	createdAt: Date;
	updatedAt: Date;
};
/** Database conversation row. */
export type MessageRecord = Omit<HelpdeskMessage, "createdAt"> & {
	createdAt: Date;
};
/** Database canned reply row. */
export type CannedReplyRecord = Omit<
	HelpdeskCannedReply,
	"createdAt" | "updatedAt"
> & { createdAt: Date; updatedAt: Date };

import { z } from "zod";
export const ticketStatusSchema = z.enum([
	"open",
	"pending",
	"resolved",
	"closed",
]);
export const ticketPrioritySchema = z.enum(["low", "medium", "high", "urgent"]);
export const idSchema = z.object({ id: z.string().min(1).max(200) });
export const paginationSchema = z.object({
	limit: z.coerce.number().int().min(1).max(100).default(50),
	offset: z.coerce.number().int().min(0).default(0),
});
export const listTicketsSchema = paginationSchema.extend({
	search: z.string().trim().normalize("NFC").max(200).optional(),
	status: ticketStatusSchema.optional(),
	priority: ticketPrioritySchema.optional(),
	assigneeId: z.string().min(1).max(200).optional(),
});
export const createTicketSchema = z
	.object({
		subject: z.string().trim().min(1).max(250),
		requesterEmail: z.email().max(320).optional(),
		body: z.string().trim().min(1).max(20000),
		priority: ticketPrioritySchema.default("medium"),
	})
	.strict();
export const customerReplySchema = z
	.object({ body: z.string().trim().min(1).max(20000) })
	.strict();
export const agentReplySchema = customerReplySchema.extend({
	isInternalNote: z.boolean().default(false),
});
export const updateTicketSchema = z
	.object({
		status: ticketStatusSchema.optional(),
		priority: ticketPrioritySchema.optional(),
		assigneeId: z.string().trim().min(1).max(200).nullable().optional(),
	})
	.strict();
export const cannedReplySchema = z
	.object({
		title: z.string().trim().min(1).max(200),
		body: z.string().trim().min(1).max(20000),
	})
	.strict();

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";
const ticketFacts = z.object({ ticketId: z.string(), customerId: z.string() });
/** Customer portal and agent permissions are separate; agents require explicit grants. */
export const helpdeskPermissions = definePermissions("helpdesk", {
	customerTicket: {
		list: permission(),
		create: permission(),
		read: permission(ticketFacts),
		reply: permission(ticketFacts),
	},
	ticket: {
		list: permission(),
		read: permission(ticketFacts),
		update: permission(ticketFacts),
		reply: permission(ticketFacts),
	},
	cannedReply: {
		list: permission(),
		create: permission(),
		update: permission(z.object({ id: z.string() })),
		delete: permission(z.object({ id: z.string() })),
	},
});

"use client";

import { lazy } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { helpdeskPermissions } from "../../permissions";
import { HelpdeskError, HelpdeskLoading, HelpdeskNotFound } from "./shared";

const Portal = lazy(() =>
	import("./pages/portal-page.internal").then((m) => ({
		default: m.PortalPage,
	})),
);
const Ticket = lazy(() =>
	import("./pages/ticket-page.internal").then((m) => ({
		default: m.TicketPage,
	})),
);
const Inbox = lazy(() =>
	import("./pages/inbox-page.internal").then((m) => ({ default: m.InboxPage })),
);
const InboxTicket = lazy(() =>
	import("./pages/inbox-ticket-page.internal").then((m) => ({
		default: m.InboxTicketPage,
	})),
);
const boundary = {
	ErrorComponent: HelpdeskError,
	LoadingComponent: HelpdeskLoading,
	NotFoundComponent: HelpdeskNotFound,
	onError: (error: Error) => console.error("[btst/helpdesk]", error),
};

/** Customer portal with a ticket creation form and protected ticket list. */
export function PortalPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/helpdesk"
			permission={helpdeskPermissions.customerTicket.list()}
			PageComponent={Portal}
		/>
	);
}
/** Customer-visible conversation. */
export function TicketPageComponent({ id }: { id: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/helpdesk/${id}`}
			PageComponent={Ticket}
			props={{ id }}
		/>
	);
}
/** Agent queue with status, priority and assignee filters. */
export function InboxPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/helpdesk/inbox"
			permission={helpdeskPermissions.ticket.list()}
			PageComponent={Inbox}
		/>
	);
}
/** Agent conversation, internal notes and ticket controls. */
export function InboxTicketPageComponent({ id }: { id: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/helpdesk/inbox/${id}`}
			PageComponent={InboxTicket}
			props={{ id }}
		/>
	);
}

"use client";

import { usePluginSiteNavigation } from "@btst/stack/context";
import { Input } from "@/components/ui/input";
import type { TicketPriority, TicketStatus } from "../../../types";
import { HELPDESK_PLUGIN_ID } from "../../constants";
import { useHelpdeskInbox } from "@btst/plugin-helpdesk/client/hooks";
import {
	Field,
	useHelpdeskListState,
	TicketSearch,
	HelpdeskPage,
	Pagination,
	SLAStatusBadge,
	StatusBadge,
	formatDate,
	priorities,
	selectClass,
	statuses,
} from "../shared";

export function InboxPage() {
	const [{ search, status, priority, assigneeId, offset }, setListState] =
		useHelpdeskListState("helpdesk-inbox");
	const { data } = useHelpdeskInbox({
		search: search || undefined,
		status: (status || undefined) as TicketStatus | undefined,
		priority: (priority || undefined) as TicketPriority | undefined,
		assigneeId: assigneeId || undefined,
		limit: 25,
		offset,
	});
	const { Link, resolve } = usePluginSiteNavigation(HELPDESK_PLUGIN_ID);
	return (
		<HelpdeskPage
			title="Support inbox"
			description="Triage tickets, track response targets, and continue customer conversations."
		>
			<TicketSearch
				search={search}
				onSearch={(value) => setListState({ search: value, offset: 0 })}
			/>
			<div className="grid gap-4 sm:grid-cols-3">
				<Field label="Filter by status">
					{(id) => (
						<select
							id={id}
							className={selectClass}
							value={status}
							onChange={(event) => {
								setListState({ status: event.target.value, offset: 0 });
							}}
						>
							<option value="">All statuses</option>
							{statuses.map((value) => (
								<option key={value} value={value}>
									{value}
								</option>
							))}
						</select>
					)}
				</Field>
				<Field label="Filter by priority">
					{(id) => (
						<select
							id={id}
							className={selectClass}
							value={priority}
							onChange={(event) => {
								setListState({ priority: event.target.value, offset: 0 });
							}}
						>
							<option value="">All priorities</option>
							{priorities.map((value) => (
								<option key={value} value={value}>
									{value}
								</option>
							))}
						</select>
					)}
				</Field>
				<Field label="Filter by assignee">
					{(id) => (
						<Input
							id={id}
							value={assigneeId}
							placeholder="All agents"
							onChange={(event) => {
								setListState({ assigneeId: event.target.value, offset: 0 });
							}}
						/>
					)}
				</Field>
			</div>
			{data.items.length ? (
				<div
					className="overflow-x-auto rounded-lg border focus-visible:outline-2 focus-visible:outline-ring"
					tabIndex={0}
					role="region"
					aria-label="Support inbox table"
				>
					<table className="min-w-[44rem] w-full text-left text-sm">
						<caption className="sr-only">
							Support ticket queue and first-response SLA status
						</caption>
						<thead className="border-b bg-muted/40">
							<tr>
								<th className="p-4 font-medium">Ticket</th>
								<th className="p-4 font-medium">Status</th>
								<th className="p-4 font-medium">Priority</th>
								<th className="p-4 font-medium">Assignee</th>
								<th className="p-4 font-medium">Response SLA</th>
							</tr>
						</thead>
						<tbody>
							{data.items.map((ticket) => (
								<tr key={ticket.id} className="border-b last:border-0">
									<td className="max-w-xs p-4">
										<Link
											href={resolve(`helpdesk/inbox/${ticket.id}`).href}
											className="inline-flex min-h-11 items-center break-words font-medium underline-offset-4 hover:underline"
										>
											{ticket.subject}
										</Link>
										<p className="text-xs text-muted-foreground">
											{ticket.customerId}
										</p>
									</td>
									<td className="p-4">
										<StatusBadge status={ticket.status} />
									</td>
									<td className="p-4 capitalize">{ticket.priority}</td>
									<td className="max-w-40 break-words p-4">
										{ticket.assigneeId || "Unassigned"}
									</td>
									<td className="p-4">
										<SLAStatusBadge ticket={ticket} />
										<p className="mt-2 text-xs text-muted-foreground">
											Due {formatDate(ticket.slaDueAt)}
										</p>
									</td>
								</tr>
							))}
						</tbody>
					</table>
				</div>
			) : (
				<p className="py-10 text-muted-foreground">
					No tickets match these filters.
				</p>
			)}
			<Pagination
				offset={offset}
				total={data.total}
				onChange={(value) => setListState({ offset: value })}
			/>
		</HelpdeskPage>
	);
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { useRegisterPageAIContext } from "@btst/stack/page-context";
import {
	PermissionAccess,
	PermissionCheck,
	usePluginOverrides,
} from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { helpdeskPermissions } from "../../../permissions";
import type {
	HelpdeskTicketDetail,
	HelpdeskCannedReply,
	TicketPriority,
	TicketStatus,
} from "../../../types";
import { HELPDESK_PLUGIN_ID } from "../../constants";
import {
	useAgentReply,
	useAgentTicket,
	useCannedReplies,
	useUpdateTicket,
} from "@btst/plugin-helpdesk/client/hooks";
import type { HelpdeskPluginOverrides } from "../../overrides";
import {
	Conversation,
	Feedback,
	Field,
	HelpdeskPage,
	HelpdeskForm,
	SLAStatusBadge,
	StatusBadge,
	formatDate,
	priorities,
	selectClass,
	statuses,
	useHelpdeskAction,
} from "../shared";

import { ticketReplyPageDescription } from "./ticket-reply-context";

function TicketReplyAIContext({
	ticket,
	cannedReplies,
	onDraft,
}: {
	ticket: HelpdeskTicketDetail;
	cannedReplies: HelpdeskCannedReply[];
	onDraft: (body: string) => void;
}) {
	useRegisterPageAIContext({
		routeName: "helpdesk-inbox-ticket",
		pageDescription: ticketReplyPageDescription(ticket, cannedReplies),
		suggestions: ["Draft a reply using the conversation and canned replies"],
		clientTools: {
			draftTicketReply: async (input) => {
				if (
					input.ticketId !== ticket.id ||
					typeof input.body !== "string" ||
					!input.body.trim() ||
					input.body.length > 20000
				)
					return {
						success: false,
						message:
							"Draft must match the current ticket and contain 1–20,000 characters.",
					};
				onDraft(input.body);
				return {
					success: true,
					message: "Draft inserted for agent review. No reply was sent.",
				};
			},
		},
	});
	return null;
}
function CannedReplyPicker({
	onSelect,
	onReplies,
}: {
	onSelect: (body: string) => void;
	onReplies: (replies: HelpdeskCannedReply[]) => void;
}) {
	const [offset, setOffset] = useState(0);
	const { data } = useCannedReplies({ limit: 25, offset });
	useEffect(() => {
		onReplies(data.items);
	}, [data.items, onReplies]);
	return (
		<div className="space-y-2">
			<Field label="Canned reply">
				{(id) => (
					<select
						id={id}
						className={selectClass}
						value=""
						onChange={(event) => {
							const reply = data.items.find(
								(item) => item.id === event.target.value,
							);
							if (reply) onSelect(reply.body);
						}}
					>
						<option value="">Insert a saved response</option>
						{data.items.map((reply) => (
							<option key={reply.id} value={reply.id}>
								{reply.title}
							</option>
						))}
					</select>
				)}
			</Field>
			{data.total > 25 && (
				<div className="flex flex-wrap items-center gap-2">
					<Button
						type="button"
						size="sm"
						variant="outline"
						disabled={offset === 0}
						onClick={() => setOffset(Math.max(0, offset - 25))}
					>
						Previous replies
					</Button>
					<Button
						type="button"
						size="sm"
						variant="outline"
						disabled={offset + 25 >= data.total}
						onClick={() => setOffset(offset + 25)}
					>
						Next replies
					</Button>
					<span className="text-xs text-muted-foreground">
						{offset + 1}–{Math.min(offset + 25, data.total)} of {data.total}
					</span>
				</div>
			)}
		</div>
	);
}
function TicketControls({ ticket }: { ticket: HelpdeskTicketDetail }) {
	const update = useUpdateTicket();
	const action = useHelpdeskAction();
	return (
		<HelpdeskForm
			disabled={update.isPending}
			className="space-y-4"
			onSubmit={(event) => {
				event.preventDefault();
				const fields = new FormData(event.currentTarget);
				void action.run(async () => {
					await update.mutateAsync({
						id: ticket.id,
						data: {
							status: fields.get("status") as TicketStatus,
							priority: fields.get("priority") as TicketPriority,
							assigneeId: String(fields.get("assigneeId") || "").trim() || null,
						},
					});
				}, "Ticket updated.");
			}}
		>
			<Field label="Status">
				{(id) => (
					<select
						key={ticket.updatedAt}
						id={id}
						name="status"
						className={selectClass}
						defaultValue={ticket.status}
					>
						{statuses.map((value) => (
							<option key={value} value={value}>
								{value}
							</option>
						))}
					</select>
				)}
			</Field>
			<Field label="Priority">
				{(id) => (
					<select
						key={ticket.updatedAt}
						id={id}
						name="priority"
						className={selectClass}
						defaultValue={ticket.priority}
					>
						{priorities.map((value) => (
							<option key={value} value={value}>
								{value}
							</option>
						))}
					</select>
				)}
			</Field>
			<Field label="Assignee ID">
				{(id) => (
					<Input
						key={ticket.updatedAt}
						id={id}
						name="assigneeId"
						defaultValue={ticket.assigneeId || ""}
						placeholder="Unassigned"
						maxLength={200}
					/>
				)}
			</Field>
			<Feedback {...action} />
			<Button disabled={update.isPending} className="min-h-11 w-full">
				{update.isPending ? "Saving…" : "Save ticket"}
			</Button>
		</HelpdeskForm>
	);
}
export function InboxTicketPage({ id }: { id: string }) {
	const { data: ticket } = useAgentTicket(id);
	const reply = useAgentReply();
	const [body, setBody] = useState("");
	const [cannedPage, setCannedPage] = useState<{
		ticketId: string;
		items: HelpdeskCannedReply[];
	} | null>(null);
	const handleCannedReplies = useCallback(
		(items: HelpdeskCannedReply[]) => setCannedPage({ ticketId: id, items }),
		[id],
	);
	const [visibility, setVisibility] = useState("public");
	useEffect(() => {
		setBody("");
		setVisibility("public");
	}, [id]);
	const action = useHelpdeskAction();
	const { renderTicketSidebar } =
		usePluginOverrides<HelpdeskPluginOverrides>(HELPDESK_PLUGIN_ID);
	return (
		<HelpdeskPage title={ticket.subject}>
			<div className="flex flex-wrap items-center gap-3">
				<StatusBadge status={ticket.status} />
				<SLAStatusBadge ticket={ticket} />
				<span className="text-sm text-muted-foreground">
					Customer: {ticket.customerId}
				</span>
			</div>
			<div className="grid min-w-0 items-start gap-6 lg:grid-cols-[minmax(0,1fr)_18rem]">
				<div className="min-w-0 space-y-6">
					<Conversation page="helpdeskInboxTicket" messages={ticket.messages} />
					{ticket.status === "closed" ? (
						<p className="text-muted-foreground">
							Reopen this ticket to send a reply or add a note.
						</p>
					) : (
						<PermissionAccess
							permission={helpdeskPermissions.ticket.reply({
								ticketId: id,
								customerId: ticket.customerId,
							})}
						>
							<>
								<PermissionCheck
									permission={helpdeskPermissions.cannedReply.list()}
								>
									{({ can }) => (
										<TicketReplyAIContext
											ticket={ticket}
											cannedReplies={
												can && cannedPage?.ticketId === id
													? cannedPage.items
													: []
											}
											onDraft={(draft) => {
												setBody(draft);
												setVisibility("public");
											}}
										/>
									)}
								</PermissionCheck>
								<HelpdeskForm
									disabled={reply.isPending}
									className="space-y-4 rounded-lg border p-4"
									onSubmit={(event) => {
										event.preventDefault();
										void action.run(
											async () => {
												await reply.mutateAsync({
													id,
													body,
													isInternalNote: visibility === "internal",
												});
												setBody("");
											},
											visibility === "internal"
												? "Internal note added. Customers cannot see this note."
												: "Public reply sent.",
										);
									}}
								>
									<div className="grid gap-4 sm:grid-cols-2">
										<Field label="Message visibility">
											{(fieldId) => (
												<select
													id={fieldId}
													className={selectClass}
													value={visibility}
													onChange={(event) =>
														setVisibility(event.target.value)
													}
												>
													<option value="public">Public reply</option>
													<option value="internal">Internal note</option>
												</select>
											)}
										</Field>
										<PermissionAccess
											permission={helpdeskPermissions.cannedReply.list()}
										>
											<CannedReplyPicker
												onSelect={setBody}
												onReplies={handleCannedReplies}
											/>
										</PermissionAccess>
									</div>
									{visibility === "internal" && (
										<p className="text-sm font-medium">
											Only support agents can see this note.
										</p>
									)}
									<Field label="Reply">
										{(fieldId) => (
											<Textarea
												id={fieldId}
												required
												rows={6}
												maxLength={20000}
												value={body}
												onChange={(event) => setBody(event.target.value)}
											/>
										)}
									</Field>
									<Feedback {...action} />
									<Button disabled={reply.isPending} className="min-h-11">
										{reply.isPending
											? "Sending…"
											: visibility === "internal"
												? "Add internal note"
												: "Send reply"}
									</Button>
								</HelpdeskForm>
							</>
						</PermissionAccess>
					)}
				</div>
				<aside
					aria-label="Ticket details"
					className="min-w-0 space-y-6 rounded-lg border p-4"
				>
					<h2 className="text-lg font-semibold">Ticket details</h2>
					<PermissionAccess
						permission={helpdeskPermissions.ticket.update({
							ticketId: id,
							customerId: ticket.customerId,
						})}
					>
						<TicketControls ticket={ticket} />
					</PermissionAccess>
					<dl className="space-y-3 break-words text-sm">
						<div>
							<dt className="text-muted-foreground">First response due</dt>
							<dd>{formatDate(ticket.slaDueAt)}</dd>
						</div>
						<div>
